        body { background: var(--bg); color: var(--text); padding: 16px; max-width: 600px; margin: 0 auto; padding-bottom: 60px; }
        h1, h2, h3 { color: var(--text); font-weight: 700; margin-bottom: 12px; }
        h1 { font-size: 1.5rem; text-align: center; margin-bottom: 24px; color: var(--accent); }
        h2 { font-size: 1.2rem; border-bottom: 1px solid var(--border); padding-bottom: 6px; margin-top: 24px; }
        .section { background: var(--card-bg); padding: 16px; border-radius: 12px; border: 1px solid var(--border); margin-bottom: 16px; }
