        input:focus, textarea:focus, select:focus { outline: none; border-color: var(--accent); }
        button { width: 100%; background: var(--accent); color: var(--bg); border: none; padding: 14px; font-size: 1rem; font-weight: 700; border-radius: 8px; cursor: pointer; transition: opacity 0.2s; }
        button:opacity { opacity: 0.9; }
        .shot-card { background: var(--bg); border: 1px solid var(--border); border-left: 4px solid var(--accent); padding: 12px; border-radius: 6px; margin-bottom: 12px; }
        .shot-header { display: flex; justify-content: space-between; font-size: 0.85rem; color: var(--accent); font-weight: bold; margin-bottom: 6px; }
        .shot-text { font-size: 0.95rem; background: transparent; border: none; color: var(--text); resize: none; width: 100%; padding: 0; margin: 0; }
        .checklist-item { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; font-size: 0.95rem; }
        .checklist-item input[type="checkbox"] { width: auto; margin-bottom: 0; }
