            <option value="Cozy / Warm / Late Night Comfort">Cozy / Warm / Late Night Comfort</option>
        </select>

        <label>Serving Context</label>
        <input type="text" id="context" placeholder="e.g., Solo midnight snack, 15-minute lazy dinner">

