    <div id="outputContainer" class="hidden">

        <h2>Shot-List Cards</h2>
        <div id="shotList"></div>

        <h2>Prop Checklist</h2>
        <div class="section" id="propChecklist"></div>

        <h2>Caption Options</h2>
        <div id="captionContainer"></div>

        <h2>Export & Execution</h2>
        <div class="section">
            <div class="action-grid">
                <button class="btn-secondary" onclick="copyFullPlan()">Copy Full Plan</button>
                <button class="btn-secondary" onclick="exportJSON()">Export JSON</button>
            </div>
        </div>
