            const dish = document.getElementById('dish').value || 'Your Dish';
            const ingredients = document.getElementById('ingredients').value || 'Pantry Staples';
            const vibe = document.getElementById('vibe').value;
            const context = document.getElementById('context').value || 'Quick meal';

