            let shots = [];
            if(vibe.includes("ASMR")) {
                shots = [
                    { type: "01. HOOK", text: `Extreme close up: Sizzling hot oil hitting ${ingredients.split(',')[0] || 'ingredients'}. Heavy audio.` },
                    { type: "02. BUILD", text: `Medium shot: Rhythmic chopping of elements. Smooth, deliberate movements.` },
                    { type: "03. CLIMAX", text: `Close up: Tossing the ${dish} in the pan, steam rising into dark lighting.` },
                    { type: "04. PAYOFF", text: `Slow motion: First bite or fork pull. Clean audio of crunch/chew.` }
                ];
            } else if(vibe.includes("Chaos")) {
                shots = [
                    { type: "01. HOOK", text: `Aggressive whip-pan to the final ${dish}. Immediate text on screen: "Stop scrolling."` },
                    { type: "02. BUILD", text: `Rapid 0.5s cuts: Throwing ingredients into the pan. High energy.` },
                    { type: "03. CLIMAX", text: `Wide shot: Pan fry execution with dramatic facial reaction or movement.` },
                    { type: "04. PAYOFF", text: `Shaky cam close-up: Shoving a massive bite toward the lens.` }
                ];
            } else { // Minimalist & Cozy Default Balance
                shots = [
                    { type: "01. HOOK", text: `Beautifully lit static shot of the completed ${dish} with steam rising.` },
                    { type: "02. BUILD", text: `Top-down layout: Neatly arranged ${ingredients}. Aesthetic assembly.` },
                    { type: "03. CLIMAX", text: `Side profile: The cooking process, focusing on color change and texture.` },
                    { type: "04. PAYOFF", text: `Macro shot: Placing the finished plate down into its serving context (${context}).` }
                ];
            }

            const shotListDiv = document.getElementById('shotList');
            shotListDiv.innerHTML = '';
            shots.forEach((shot, i) => {
                shotListDiv.innerHTML += `
                    <div class="shot-card">
                        <div class="shot-header"><span>${shot.type}</span><span>Editable</span></div>
                        <textarea class="shot-text" rows="2" id="shot_${i}">${shot.text}</textarea>
                    </div>`;
            });

            // 2. Generate Props Checklist
            const props = ["Smartphone/Camera", "Tripod / Overhead Mount", "Primary Skillet/Pan", "Serving Plate/Bowl", "Aesthetic Utensil", "Damp cloth (for instant spill wipes)"];
            const propDiv = document.getElementById('propChecklist');
            propDiv.innerHTML = '';
            props.forEach((prop, i) => {
                propDiv.innerHTML += `
                    <div class="checklist-item">
                        <input type="checkbox" id="prop_${i}">
                        <label for="prop_${i}" style="margin:0; text-transform:none; color:var(--text); font-weight:normal;">${prop}</label>
                    </div>`;
            });

            // 3. Generate Captions
            const captions = [
`【 Hook 】The 15-minute fix you needed.
【 Context 】When it's late, you're lazy, but you want restaurant-quality ${dish}.
【 Blueprint 】Using just ${ingredients}. 
#cooking #recipe #foodtok #easyrecipes`,

`POV: You realized you have ${ingredients} in your kitchen right now. 
Stop ordering takeout. Make this ${dish} instead. Perfect for a ${context}.
Recipe details in the comments.`,

`Current status: Tuning out the world with some ${vibe.split(' / ')[0]} cooking. 
Dish: ${dish}
Vibe: ${context}
Rate this setup 1-10.`
            ];

            const captionContainer = document.getElementById('captionContainer');
            captionContainer.innerHTML = '';
            captions.forEach((cap, i) => {
                captionContainer.innerHTML += `
                    <div class="caption-box">
                        <button class="copy-btn" onclick="copyText('cap_${i}')">Copy</button>
                        <span id="cap_${i}">${cap}</span>
                    </div>`;
            });

            document.getElementById('outputContainer').classList.remove('hidden');
            document.getElementById('outputContainer').scrollIntoView({ behavior: 'smooth' });
        }

        function copyText(id) {
            const text = document.getElementById(id).innerText;
            navigator.clipboard.writeText(text);
            alert('Copied to clipboard');
        }

        function gatherFullPlanText() {
            let plan = `REEL BLUEPRINT PLAN\n===================\n`;
            plan += `Dish: ${document.getElementById('dish').value}\n`;
            plan += `Vibe: ${document.getElementById('vibe').value}\n\n`;
            plan += `SHOT LIST:\n`;

            const shotTexts = document.querySelectorAll('.shot-text');
            shotTexts.forEach((textarea, i) => {
                plan += `- Shot ${i+1}: ${textarea.value}\n`;
            });

            plan += `\nCAPTIONS:\n`;
            const caps = [0,1,2];
            caps.forEach(i => {
                const el = document.getElementById(`cap_${i}`);
                if(el) plan += `\nOption ${i+1}:\n${el.innerText}\n`;
            });
            return plan;
        }

        function copyFullPlan() {
            navigator.clipboard.writeText(gatherFullPlanText());
            alert('Full structural plan copied!');
        }

        function exportJSON() {
            const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify({
                dish: document.getElementById('dish').value,
                vibe: document.getElementById('vibe').value,
                shots: Array.from(document.querySelectorAll('.shot-text')).map(t => t.value)
            }, null, 2));
            const downloadAnchor = document.createElement('a');
            downloadAnchor.setAttribute("href", dataStr);
            downloadAnchor.setAttribute("download", "reel_blueprint.json");
            document.body.appendChild(downloadAnchor);
            downloadAnchor.click();
            downloadAnchor.remove();
        }
    </script>
</body>
</html>

